// [UNITY-SKILL:SPRITEATLAS]
// [TYPE:PREBUILD]
// Generated by SpriteAtlas V2 Skill
// Automatically generates Built-in Data SpriteAtlas V2 assets during prebuild

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.U2D;
using UnityEngine;
using UnityEngine.U2D;

namespace IntergalacticNinja.Editor
{
    public class SpriteAtlasPrebuildGenerator : IPreprocessBuildWithReport
    {
        public int callbackOrder => 0;

        private const string AtlasOutputDir = "Assets/Atlases";

        public void OnPreprocessBuild(BuildReport report)
        {
            GenerateAllAtlases();
        }

        public static string[] GenerateAllAtlases()
        {
            // CRITICAL: Enable Sprite Packer V2 mode before generating/packing atlases
            EditorSettings.spritePackerMode = SpritePackerMode.SpriteAtlasV2;

            var generated = new List<string>();

            // Built-in Data delivery (includeInBuild = true) for immediate scene loading
            TryAdd(generated, GenerateAtlasFromFolders(
                new[] { "Assets/Design/Images/CockpitActionHub" },
                AtlasOutputDir + "/CockpitActionHub_UI_Atlas.spriteatlasv2",
                includeInBuild: true,
                tightPacking: false,
                pathFilter: path =>
                    path.EndsWith(".png", StringComparison.OrdinalIgnoreCase) &&
                    Path.GetFileName(path).StartsWith("CockpitActionHub_dev01_", StringComparison.OrdinalIgnoreCase)));

            TryAdd(generated, GenerateAtlasFromFolders(
                new[] { "Assets/Design/Animation/Hacking" },
                AtlasOutputDir + "/Hacking_Animations_Atlas.spriteatlasv2",
                includeInBuild: true,
                tightPacking: true));

            // Only referenced NinjaHero element animations (excludes unreferenced Destroy/ folders and full-screen Background/)
            TryAdd(generated, GenerateAtlasFromFolders(
                new[]
                {
                    "Assets/Design/Animation/NinjaHero/DefaultElement",
                    "Assets/Design/Animation/NinjaHero/Element1/Idle",
                    "Assets/Design/Animation/NinjaHero/Element2/Idle"
                },
                AtlasOutputDir + "/NinjaHero_Elements_Atlas.spriteatlasv2",
                includeInBuild: true,
                tightPacking: true));

            TryAdd(generated, GenerateAtlasFromFolders(
                new[] { "Assets/Design/Animations/WallJumping" },
                AtlasOutputDir + "/WallJumping_Animations_Atlas.spriteatlasv2",
                includeInBuild: true,
                tightPacking: true));

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            return generated.ToArray();
        }

        private static void TryAdd(List<string> list, string atlasPath)
        {
            if (!string.IsNullOrEmpty(atlasPath))
                list.Add(atlasPath);
        }

        private static bool IsValidProjectSprite(string assetPath)
        {
            return !string.IsNullOrEmpty(assetPath) &&
                   assetPath.StartsWith("Assets/", StringComparison.Ordinal) &&
                   !assetPath.Contains("/Packages/");
        }

        private static string GenerateAtlasFromFolders(
            string[] spriteFolders,
            string atlasPath,
            bool includeInBuild,
            bool tightPacking,
            Func<string, bool> pathFilter = null)
        {
            string[] validFolders = spriteFolders.Where(AssetDatabase.IsValidFolder).ToArray();
            if (validFolders.Length == 0)
                return null;

            string[] guids = AssetDatabase.FindAssets("t:Sprite", validFolders);
            UnityEngine.Object[] sprites = guids
                .Select(AssetDatabase.GUIDToAssetPath)
                .Distinct()
                .Where(IsValidProjectSprite)
                .Where(path => pathFilter == null || pathFilter(path))
                .OrderBy(path => path, StringComparer.Ordinal)
                .Select(AssetDatabase.LoadAssetAtPath<Sprite>)
                .Where(sprite => sprite != null)
                .Cast<UnityEngine.Object>()
                .ToArray();

            if (sprites.Length == 0)
                return null;

            string directory = Path.GetDirectoryName(atlasPath);
            if (!string.IsNullOrEmpty(directory) && !Directory.Exists(directory))
                Directory.CreateDirectory(directory);

            SpriteAtlasAsset atlasAsset;
            if (File.Exists(atlasPath))
            {
                atlasAsset = SpriteAtlasAsset.Load(atlasPath);
                var existingRuntimeAtlas = AssetDatabase.LoadAssetAtPath<SpriteAtlas>(atlasPath);
                if (existingRuntimeAtlas != null)
                {
                    UnityEngine.Object[] existingPackables = existingRuntimeAtlas.GetPackables();
                    if (existingPackables != null && existingPackables.Length > 0)
                        atlasAsset.Remove(existingPackables);
                }
            }
            else
            {
                atlasAsset = new SpriteAtlasAsset();
            }

            atlasAsset.Add(sprites);
            SpriteAtlasAsset.Save(atlasAsset, atlasPath);
            AssetDatabase.ImportAsset(atlasPath);

            ConfigureAtlasImporter(atlasPath, includeInBuild, tightPacking);
            return atlasPath;
        }

        private static void ConfigureAtlasImporter(string atlasPath, bool includeInBuild, bool tightPacking)
        {
            var importer = AssetImporter.GetAtPath(atlasPath) as SpriteAtlasImporter;
            if (importer == null)
                return;

            var textureSettings = importer.textureSettings;
            textureSettings.filterMode = FilterMode.Bilinear;
            textureSettings.generateMipMaps = false;
            textureSettings.sRGB = true;
            importer.textureSettings = textureSettings;

            var packingSettings = importer.packingSettings;
            packingSettings.padding = 4;
            packingSettings.enableTightPacking = tightPacking;
            packingSettings.enableRotation = false;
            packingSettings.enableAlphaDilation = true;
            importer.packingSettings = packingSettings;

            var androidSettings = new TextureImporterPlatformSettings
            {
                name = "Android",
                overridden = true,
                maxTextureSize = 2048,
                format = TextureImporterFormat.ASTC_6x6,
                textureCompression = TextureImporterCompression.Compressed,
                compressionQuality = 50
            };
            importer.SetPlatformSettings(androidSettings);

            importer.includeInBuild = includeInBuild;
            importer.SaveAndReimport();
        }
    }
}
